generator client {
  provider        = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

// Users
model User {
  id         Int      @id @default(autoincrement())
  username   String   @unique
  email      String   @unique
  password   String
  token      String?
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  // Profile
  Profile    Profile? @relation(fields: [id], references: [userId])

  // Articles authored
  Article    Article[] @relation("ArticleAuthor", references: [id])

  // Follows (following/followers) - optional for spec
  Follow     Follow[] @relation("FollowTo", references: [followingId])
  Follow     Follow[] @relation("FollowFrom", references: [followerId])

  // Auth tokens
  Token      Token[] @relation("TokenOwner", references: [userId])
}

// Profiles
model Profile {
  id         Int    @id @default(autoincrement())
  userId     Int    @unique @default(autoincrement())
  bio        String?
  image      String?
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  User       User   @relation("Profile", fields: [userId], references: [id])
}

// Articles
model Article {
  id          Int      @id @default(autoincrement())
  slug        String   @unique
  title       String
  description String
  body        String
  tagList     String[]  // simple array of strings for spec
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  // Authorship
  author      User     @relation("ArticleAuthor", fields: [id], references: [id])

  // Tags (many-to-many)
  tags       ArticleTag[]

  // Comments
  comments   Comment[] @relation("ArticleComments", references: [articleId])

  // Favorited by users
  favorites  Favorite[] @relation("ArticleFavorite", references: [articleId])

  // Feed entries for users
  feed       Feed[] @relation("UserFeed", references: [userId])
}

// ArticleTag pivot
model ArticleTag {
  id      Int      @id @default(autoincrement())
  tagName String  @unique
  articleId Int
  article   Article @relation("ArticleTags", fields: [articleId], references: [id])

  @@unique([articleId, tagName])
}

// Comments
model Comment {
  id          Int      @id @default(autoincrement())
  articleId   Int
  parentId    Int?
  body        String
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  article     Article @relation("ArticleComments", fields: [articleId], references: [id])
  parent      Comment  @relation("CommentReplies", fields: [id], references: [parentId])
  author      User    @relation("CommentAuthor", fields: [id], references: [id])
  favorited   Boolean @default(false)
  favoritesCount Int  @default(0)

  @@index([articleId, parentId])
}

// Favorites (many-to-many)
model Favorite {
  id      Int      @id @default(autoincrement())
  articleId Int
  userId   Int
  article  Article  @relation("ArticleFavorite", fields: [articleId], references: [id])
  user    User     @relation("FavoriteUser", fields: [userId], references: [id])

  @@unique([articleId, userId])
}

// Feed (for user-specific feeds)
model Feed {
  id        Int      @id @default(autoincrement())
  userId    Int
  feed      Json
  updatedAt DateTime @default(now())

  user      User   @relation("UserFeed", fields: [userId], references: [id])
}

// Tokens (for JWT management)
model Token {
  id       Int      @id @default(autoincrement())
  userId   Int
  token    String
  expires  DateTime?

  user     User    @relation("TokenOwner", fields: [userId], references: [id])
}

// Follows (optional for social features)
model Follow {
  followerId Int
  followingId Int
  createdAt  DateTime @default(now())

  User follower @relation("FollowTo", fields: [followerId], references: [id])
  User following @relation("FollowFrom", fields: [followingId], references: [id])

  @@id([followerId, followingId])
  @@index([followerId, followingId])
}

